#!/usr/bin/env python3
"""Compose the math pilot results (M1–M5) into a markdown section for the plan.
Usage: python3 report_math.py <pilot_root> <m3_dir_or_-> <out.md>"""
import json, os, sys
P, M3D, OUT = sys.argv[1:4]
J = lambda p: json.load(open(p)) if os.path.exists(p) else None
m1, m2, m5 = J(f'{P}/M1/summary.json'), J(f'{P}/M2/summary.json'), J(f'{P}/M5_heldout/summary.json'); m3 = J(f'{M3D}/armB_summary.json') if M3D != '-' else None
pct = lambda x: '–' if x is None else f'{100*x:.1f}%'
md = ['## 6. Pilot results (9 September 2026; Sol gpt-5.6-sol medium for translation and problem writing, high effort for solving; Luna gpt-5.6-luna as the second solver)\n']
if m1:
    md += [f"**M1 · translation fidelity.** {m1['n']} rows (300 GSM8K train, 300 MATH train levels 1–3) translated and localised, then solved blind from the Greek text: **{pct(m1['rate'])}** reach the reference answer — GSM8K {pct(m1['by_source']['gsm8k']['rate'])}, MATH {pct(m1['by_source']['math']['rate'])}. By MATH level: " + ', '.join(f"{k} {pct(v['rate'])}" for k, v in m1['by_level'].items() if k != 'gsm') + f". Formatting (M4) on the same solutions: decimal comma {pct(m1['formatting']['decimal_comma_ok'])}, answer line {pct(m1['formatting']['answer_line'])}, euro after the number {pct(m1['formatting']['euro_after_number'])}.\n",
           "The residual MATH failures are mostly representation, not arithmetic: a matrix written as a tuple, «περιττή» for `\\text{odd}`, a Greek capital Α for a Latin A. The first scoring run reported 46% because Sol writes «750 μήλα» where the reference is 750; the equivalence checker now ignores trailing units, accepts Greek and English number formats, the Unicode minus, fractions with thousands separators, multi-part answers by their number sequence, and rounding within half a cent or 0.1%.\n"]
if m2:
    md += [f"**M2 · native problems.** {m2['n']} problems written by Sol over grade × topic × context × surface cells, solved blind by Luna: final answers agree in **{pct(m2['rate'])}** (62% under the string checker before the fixes). By surface: " + ', '.join(f"{k} {pct(v['rate'])}" for k, v in m2['by_surface'].items()) + '. Weakest topics: ' + ', '.join(f"{t} {pct(v['rate'])}" for t, v in sorted(m2['by_topic'].items(), key=lambda kv: kv[1]['rate'])[:4]) + f". Formatting: decimal comma {pct(m2['formatting']['decimal_comma_ok'])}, answer line {pct(m2['formatting']['answer_line'])}, euro after the number {pct(m2['formatting']['euro_after_number'])}.\n",
           "Two-part problems (α)(β) agree as often as single-answer ones once compared part by part, but they make a row's answer harder to verify exactly; the production set keeps them only with a fixed «α) …· β) …» answer format on both sides.\n"]
if m3:
    md += [f"**M3 · difficulty calibration on arm B** ({m3['n']} native problems, greedy plus 3 samples through vLLM): greedy accuracy **{pct(m3['greedy_acc'])}**, pass@4 {pct(m3['pass_at_k'])}, mean sample accuracy {pct(m3['mean_sample_acc'])}. By grade: " + ', '.join(f"{g} {pct(v['greedy'])}" for g, v in m3['by_grade'].items()) + '. Weakest topics: ' + ', '.join(f"{t} {pct(v['greedy'])}" for t, v in sorted(m3['by_topic'].items(), key=lambda kv: kv[1]['greedy'])[:4]) + f". Formatting of arm B's solutions: decimal comma {pct(m3['formatting']['decimal_comma_ok'])}, answer line {pct(m3['formatting']['answer_line'])}, euro after the number {pct(m3['formatting']['euro_after_number'])}; over-long answers {pct(m3['loop_rate'])}.\n"]
if m5:
    md += [f"**M5 · held-out set.** {m5['n']} native problems from a different seed, two-solve agreement {pct(m5.get('rate', m5.get('agree')))}; the agreeing rows become the fixed Greek evaluation set (never trained on). Overlap with Greek MGSM (250 test problems): no pilot problem above 0.25 character 5-gram Jaccard against any MGSM problem, so translation of GSM8K *train* and native writing are both clean.\n"]
md += ['**What the pilots decide.** Translation of GSM8K and MATH with reference answers is reliable enough to keep every row whose Greek solve reaches the reference (a free correctness filter at 95%); native generation with two independent solves keeps about 97% of rows; the formatting rules are followed without a repair pass; the mix should lean to the topics arm B fails (M3) rather than uniform. Scale per §6 of the plan: 20k first cut.\n']
open(OUT, 'w').write('\n'.join(md)); print('wrote', OUT)
